import 'package:flutter/material.dart';
import 'package:niwar_devforge_flutter_auth/niwar_devforge_flutter_auth.dart';

import 'src/auth_screen.dart';

const _configuredBackendApiBaseUrl = String.fromEnvironment(
  'DEVFORGE_BACKEND_API_BASE_URL',
);
const _allowInsecureLocalhost = bool.fromEnvironment(
  'DEVFORGE_ALLOW_INSECURE_LOCALHOST',
  defaultValue: false,
);

void main() {
  final client = _configuredClient();
  if (client == null) {
    runApp(const _ConfigurationErrorApp());
    return;
  }
  runApp(GeneratedMobileAuthApp(client: client));
}

DevForgeMobileAuthClient? _configuredClient() {
  if (_configuredBackendApiBaseUrl.isEmpty) return null;
  try {
    return DevForgeMobileAuthClient(
      backendApiBaseUrl: Uri.parse(_configuredBackendApiBaseUrl),
      sessionVault: SecureSessionVault(FlutterSecureStorageSecretStore()),
      allowInsecureLocalhostForDevelopment: _allowInsecureLocalhost,
    );
  } on Object {
    return null;
  }
}

class GeneratedMobileAuthApp extends StatelessWidget {
  const GeneratedMobileAuthApp({required this.client, super.key});

  final DevForgeMobileAuthClient client;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: '{{PRODUCT_NAME}}',
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.indigo),
        useMaterial3: true,
      ),
      home: AuthScreen(
        client: client,
        productName: '{{PRODUCT_NAME}}',
      ),
    );
  }
}

class _ConfigurationErrorApp extends StatelessWidget {
  const _ConfigurationErrorApp();

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: const Scaffold(
        body: Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text(
              'Backend configuration is missing or invalid.',
              textAlign: TextAlign.center,
            ),
          ),
        ),
      ),
    );
  }
}

