import 'package:flutter/material.dart';
import 'package:niwar_devforge_flutter_auth/niwar_devforge_flutter_auth.dart';

class AuthScreen extends StatefulWidget {
  const AuthScreen({
    required this.client,
    required this.productName,
    super.key,
  });

  final DevForgeMobileAuthClient client;
  final String productName;

  @override
  State<AuthScreen> createState() => _AuthScreenState();
}

class _AuthScreenState extends State<AuthScreen> {
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();
  final _displayNameController = TextEditingController();

  UserProfile? _profile;
  String _status = 'loading';
  String? _message;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _startInitialLoad();
  }

  Future<void> _startInitialLoad() async {
    await _refreshProfile();
  }

  @override
  void dispose() {
    _emailController.dispose();
    _passwordController.dispose();
    _displayNameController.dispose();
    super.dispose();
  }

  Future<void> _refreshProfile() async {
    try {
      final profile = await widget.client.currentProfile();
      if (!mounted) return;
      setState(() {
        _profile = profile;
        _status = profile == null ? 'anonymous' : 'authenticated';
        if (profile?.displayName != null) {
          _displayNameController.text = profile!.displayName!;
        }
      });
    } on Object catch (error) {
      if (!mounted) return;
      setState(() {
        _profile = null;
        _status = 'error';
        _message = _publicErrorCode(error);
      });
    }
  }

  Future<void> _execute(Future<void> Function() action) async {
    if (_busy) return;
    setState(() {
      _busy = true;
      _message = null;
    });
    try {
      await action();
    } on Object catch (error) {
      if (!mounted) return;
      setState(() {
        _message = _publicErrorCode(error);
      });
    } finally {
      if (mounted) {
        setState(() {
          _busy = false;
        });
      }
    }
  }

  Future<void> _register() => _execute(() async {
    final profile = await widget.client.register(
      email: _emailController.text.trim(),
      password: _passwordController.text,
      displayName: _displayNameController.text.trim().isEmpty
          ? null
          : _displayNameController.text.trim(),
    );
    if (!mounted) return;
    setState(() {
      _message = 'registered:${profile.email}';
    });
  });

  Future<void> _login() => _execute(() async {
    await widget.client.login(
      identifier: _emailController.text.trim(),
      password: _passwordController.text,
    );
    final profile = await widget.client.currentProfile();
    if (!mounted) return;
    setState(() {
      _profile = profile;
      _status = profile == null ? 'anonymous' : 'authenticated';
      _message = profile == null ? 'profile_unavailable' : 'authenticated';
    });
  });

  Future<void> _updateProfile() => _execute(() async {
    final profile = await widget.client.updateProfile(
      displayName: _displayNameController.text.trim().isEmpty
          ? null
          : _displayNameController.text.trim(),
    );
    if (!mounted) return;
    setState(() {
      _profile = profile;
      _status = 'authenticated';
      _message = 'profile_updated';
    });
  });

  Future<void> _logout() => _execute(() async {
    await widget.client.logout();
    if (!mounted) return;
    setState(() {
      _profile = null;
      _status = 'anonymous';
      _message = 'logged_out';
    });
  });

  String _publicErrorCode(Object error) {
    if (error is AuthApiException) return error.code;
    if (error is AuthTransportException) return error.code;
    if (error is AuthSessionStateException) return error.code;
    if (error is AuthSessionStorageException) return error.code;
    if (error is InvalidAuthResponse) return error.code;
    return 'unexpected_error';
  }

  @override
  Widget build(BuildContext context) {
    final profile = _profile;
    return Scaffold(
      appBar: AppBar(title: Text(widget.productName)),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.all(20),
          children: [
            Text(
              'Status: $_status',
              key: const Key('session-status'),
              style: Theme.of(context).textTheme.titleMedium,
            ),
            if (profile != null) ...[
              const SizedBox(height: 8),
              Text(profile.email, key: const Key('profile-email')),
              Text(
                profile.displayName ?? '',
                key: const Key('profile-display-name'),
              ),
            ],
            const SizedBox(height: 20),
            TextField(
              key: const Key('email'),
              controller: _emailController,
              keyboardType: TextInputType.emailAddress,
              autocorrect: false,
              decoration: const InputDecoration(labelText: 'Email'),
            ),
            const SizedBox(height: 12),
            TextField(
              key: const Key('password'),
              controller: _passwordController,
              obscureText: true,
              enableSuggestions: false,
              autocorrect: false,
              decoration: const InputDecoration(labelText: 'Password'),
            ),
            const SizedBox(height: 12),
            TextField(
              key: const Key('display-name'),
              controller: _displayNameController,
              decoration: const InputDecoration(labelText: 'Display name'),
            ),
            const SizedBox(height: 20),
            FilledButton(
              key: const Key('register'),
              onPressed: _busy ? null : _register,
              child: const Text('Register'),
            ),
            const SizedBox(height: 8),
            FilledButton.tonal(
              key: const Key('login'),
              onPressed: _busy ? null : _login,
              child: const Text('Login'),
            ),
            const SizedBox(height: 8),
            OutlinedButton(
              key: const Key('update-profile'),
              onPressed: _busy || profile == null ? null : _updateProfile,
              child: const Text('Update profile'),
            ),
            const SizedBox(height: 8),
            OutlinedButton(
              key: const Key('logout'),
              onPressed: _busy || profile == null ? null : _logout,
              child: const Text('Logout'),
            ),
            if (_message != null) ...[
              const SizedBox(height: 16),
              Text(_message!, key: const Key('message')),
            ],
          ],
        ),
      ),
    );
  }
}

