import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:niwar_devforge_flutter_auth/niwar_devforge_flutter_auth.dart';

import 'package:{{PACKAGE_NAME}}/main.dart';

void main() {
  testWidgets('generated mobile auth flow keeps the session token out of UI', (
    tester,
  ) async {
    final store = _MemorySecretStore();
    final transport = _ScriptedTransport();
    final client = DevForgeMobileAuthClient(
      backendApiBaseUrl: Uri.parse('http://127.0.0.1:8000/api/v1/'),
      sessionVault: SecureSessionVault(store),
      transport: transport,
      allowInsecureLocalhostForDevelopment: true,
    );

    await tester.pumpWidget(GeneratedMobileAuthApp(client: client));
    await tester.pumpAndSettle();

    expect(find.text('Status: anonymous'), findsOneWidget);

    await tester.enterText(
      find.byKey(const Key('email')),
      'mobile@example.test',
    );
    await tester.enterText(
      find.byKey(const Key('password')),
      'Generated-Mobile-Password-2026!',
    );
    await tester.enterText(
      find.byKey(const Key('display-name')),
      'Generated Mobile User',
    );

    final registerButton = find.byKey(const Key('register'));
    await tester.ensureVisible(registerButton);
    await tester.tap(registerButton);
    await tester.pumpAndSettle();
    expect(find.text('registered:mobile@example.test'), findsOneWidget);

    final loginButton = find.byKey(const Key('login'));
    await tester.ensureVisible(loginButton);
    await tester.tap(loginButton);
    await tester.pumpAndSettle();
    expect(find.text('Status: authenticated'), findsOneWidget);
    final profileEmail = tester.widget<Text>(
      find.byKey(const Key('profile-email')),
    );
    expect(profileEmail.data, 'mobile@example.test');
    expect(find.textContaining(_ScriptedTransport.sessionToken), findsNothing);
    expect(store.values.values, contains(_ScriptedTransport.sessionToken));

    await tester.enterText(
      find.byKey(const Key('display-name')),
      'Updated Mobile User',
    );
    final updateProfileButton = find.byKey(const Key('update-profile'));
    await tester.ensureVisible(updateProfileButton);
    await tester.tap(updateProfileButton);
    await tester.pumpAndSettle();
    final profileDisplayName = tester.widget<Text>(
      find.byKey(const Key('profile-display-name')),
    );
    expect(profileDisplayName.data, 'Updated Mobile User');
    expect(find.text('profile_updated'), findsOneWidget);
    expect(find.textContaining(_ScriptedTransport.sessionToken), findsNothing);

    final logoutButton = find.byKey(const Key('logout'));
    await tester.ensureVisible(logoutButton);
    await tester.tap(logoutButton);
    await tester.pumpAndSettle();
    expect(find.text('Status: anonymous'), findsOneWidget);
    expect(find.text('logged_out'), findsOneWidget);
    expect(store.values, isEmpty);
    expect(find.textContaining(_ScriptedTransport.sessionToken), findsNothing);
  });
}

final class _MemorySecretStore implements SecretStore {
  final Map<String, String> values = <String, String>{};

  @override
  Future<void> delete({required String key}) async {
    values.remove(key);
  }

  @override
  Future<String?> read({required String key}) async => values[key];

  @override
  Future<void> write({required String key, required String value}) async {
    values[key] = value;
  }
}

final class _ScriptedTransport implements AuthHttpTransport {
  static const sessionToken = 'generated-mobile-session-token-1234567890';

  @override
  Future<AuthHttpResponse> send(
    Uri uri, {
    required String method,
    Map<String, String>? headers,
    String? body,
    Duration timeout = const Duration(seconds: 15),
  }) async {
    if (uri.path.endsWith('/auth/register') && method == 'POST') {
      return _json(201, <String, Object?>{
        'user_id': 'mobile-user-1',
        'email': 'mobile@example.test',
        'display_name': 'Generated Mobile User',
        'is_active': true,
      });
    }

    if (uri.path.endsWith('/auth/session') && method == 'POST') {
      return _json(200, <String, Object?>{
        'session_token': sessionToken,
        'token_type': 'bearer',
        'expires_in_seconds': 3600,
      });
    }

    if (uri.path.endsWith('/users/me') && method == 'GET') {
      _expectBearer(headers);
      return _json(200, <String, Object?>{
        'user_id': 'mobile-user-1',
        'email': 'mobile@example.test',
        'display_name': 'Generated Mobile User',
        'is_active': true,
      });
    }

    if (uri.path.endsWith('/users/me/profile') && method == 'PATCH') {
      _expectBearer(headers);
      return _json(200, <String, Object?>{
        'user_id': 'mobile-user-1',
        'email': 'mobile@example.test',
        'display_name': 'Updated Mobile User',
        'is_active': true,
      });
    }

    if (uri.path.endsWith('/auth/session') && method == 'DELETE') {
      _expectBearer(headers);
      return const AuthHttpResponse(statusCode: 204, headers: {}, body: '');
    }

    return _json(500, <String, Object?>{'code': 'unexpected_test_request'});
  }

  void _expectBearer(Map<String, String>? headers) {
    expect(headers?['Authorization'], 'Bearer $sessionToken');
  }

  AuthHttpResponse _json(int statusCode, Map<String, Object?> body) {
    return AuthHttpResponse(
      statusCode: statusCode,
      headers: const <String, String>{'content-type': 'application/json'},
      body: jsonEncode(body),
    );
  }
}

