import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:niwar_devforge_flutter_auth/niwar_devforge_flutter_auth.dart';

void main() {
  test(
    'generated mobile product authenticates against the real backend',
    () async {
      final configuredUrl = Platform.environment['DEVFORGE_REAL_BACKEND_URL'];
      expect(
        configuredUrl,
        isNotNull,
        reason: 'DEVFORGE_REAL_BACKEND_URL must be set for this proof',
      );

      final store = _MemorySecretStore();
      final client = DevForgeMobileAuthClient(
        backendApiBaseUrl: Uri.parse(configuredUrl!),
        sessionVault: SecureSessionVault(store),
        allowInsecureLocalhostForDevelopment: true,
      );

      final unique = DateTime.now().microsecondsSinceEpoch;
      final email = 'generated-mobile-$unique@example.test';
      const password = 'Generated-Mobile-Password-2026!';

      final registered = await client.register(
        email: email,
        password: password,
        displayName: 'Generated Mobile Runtime',
      );
      expect(registered.email, email);

      final login = await client.login(identifier: email, password: password);
      expect(login.authenticated, isTrue);

      final storedToken = store.values.values
          .where((value) => value.length >= 16)
          .fold<String?>(null, (current, value) {
            if (current == null || value.length > current.length) return value;
            return current;
          });
      expect(storedToken, isNotNull);
      final secret = storedToken!;
      expect(login.toString(), isNot(contains(secret)));

      final profile = await client.currentProfile();
      expect(profile, isNotNull);
      final authenticatedProfile = profile!;
      expect(authenticatedProfile.email, email);
      expect(authenticatedProfile.email, isNot(contains(secret)));

      final updated = await client.updateProfile(
        displayName: 'Generated Mobile Updated',
      );
      expect(updated.displayName, 'Generated Mobile Updated');
      expect(updated.displayName, isNot(contains(secret)));

      final logout = await client.logout();
      expect(logout.serverSessionEnded, isTrue);
      expect(store.values, isEmpty);
      expect(await client.currentProfile(), isNull);
    },
  );
}

final class _MemorySecretStore implements SecretStore {
  final Map<String, String> values = <String, String>{};

  @override
  Future<void> delete({required String key}) async {
    values.remove(key);
  }

  @override
  Future<String?> read({required String key}) async => values[key];

  @override
  Future<void> write({required String key, required String value}) async {
    values[key] = value;
  }
}
